[5234]={["aftermath"]="Vandis counted three cauldrons available for sabotage and prepared the final western assignment.",["atomIDs"]={"5234:description:1-179","5234:description:184-295","5234:objective:1-102"},["endingAtomIDs"]={"5234:completion:1-36","5234:completion:38-108","5234:completion:110-246","5234:completion:251-411","5234:completion:413-500"},["opening"]="The Haunt's sample moved inside fragile glass instead of beneath the platform. Its return would add a third composition to Dithers's analysis.",["pending"]="{actor} meant to bring the Haunt bottle back to Vandis.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} delivered the third sample.",["sourceHash"]="4a815db7a2d9bcb65c3f1f8e5b53256a045210f2f1232f4c820f0bce6b913057",["sourceRaceMask"]="?",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
[5235]={["aftermath"]="Soulwrath's key dissolved against the lock and the panel opened over viscous toxin.",["atomIDs"]={"5235:description:1-83","5235:description:86-175","5235:description:178-213","5235:description:218-379","5235:description:382-437","5235:description:440-506","5235:objective:1-150","5235:objective:153-271"},["endingAtomIDs"]={"5235:completion:1-126","5235:completion:128-263","5235:completion:268-409"},["opening"]="Far from the Bulwark, the last farm stood near the eastern border. Ghosts and wraiths made this cauldron's defenses tougher than the first field's inexperienced troops.",["pending"]="{actor} intended to unlock Gahrron's cauldron.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} gained access to the final vessel.",["sourceHash"]="60d4fd054d532ef1ce59268d5fe8851d265866431a9ce65b2a1da0dfde2483d7",["sourceRaceMask"]="178",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
