[5661]={["aftermath"]="Aelthalyste welcomed another pupil and urged readiness for the lessons and tests ahead.",["atomIDs"]={"5661:description:1-59","5661:description:61-185","5661:description:190-299","5661:description:304-367","5661:objective:1-38"},["endingAtomIDs"]={"5661:completion:1-30","5661:completion:32-90","5661:completion:92-160","5661:completion:162-194","5661:completion:196-238"},["opening"]="A message heard in Bloodhoof Village called Forsaken pupils to Aelthalyste. Even while seeking priests of another tribe, the messenger could point the traveler toward the War Quarter.",["pending"]="{actor} planned to speak with Aelthalyste in the Undercity.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} met Aelthalyste in the War Quarter.",["sourceHash"]="b97bfe0bf9f56f81e0bd2fb6f5e8f481db017923d41b81d2f83635bd2fd47d08",["sourceRaceMask"]="16",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
