[5673]={["aftermath"]="Alathea welcomed the swift return and offered time to rest before discussing the next stage of training.",["atomIDs"]={"5673:description:1-121","5673:description:123-182","5673:description:184-327","5673:description:332-388","5673:objective:1-40"},["endingAtomIDs"]={"5673:completion:1-47","5673:completion:49-145","5673:completion:147-209","5673:completion:211-303"},["opening"]="Laurena could offer many lessons, but Elune's particular gifts belonged to teachers of that faith. She directed the pupil back to Alathea for the test at the Temple of the Moon.",["pending"]="{actor} intended to return to Alathea in Darnassus.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} reached Alathea at the Temple of the Moon.",["sourceHash"]="1c541b1506d550ec2a1ef6b8390bdc2835c97879d70937b0516a13b012f4ac0d",["sourceRaceMask"]="8",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639"},
